// Pasta padrão: tudo o que já existia fica aqui. Outras pastas = programações de outra pessoa ou lugar.
const PASTA_CT = "TREINO CT CANTIL";
const pastaDe = (p) => (p.pasta || "").trim() || PASTA_CT;
const mesmaPasta = (a, b) => normalizarTexto(a) === normalizarTexto(b);
const DIAS_SEMANA = ["SEG", "TER", "QUA", "QUI", "SEX", "SÁB", "DOM"];
const NOMES_DIA = { SEG: "Segunda", TER: "Terça", QUA: "Quarta", QUI: "Quinta", SEX: "Sexta", "SÁB": "Sábado", DOM: "Domingo" };
// Objetivos / aptidões que aparecem ao lado de cada exercício (dá para digitar outro em "Outro…")
const APTIDOES = [
  "Aquecimento", "Cardiorrespiratória", "Resistência muscular localizada", "Resistência", "Força", "Potência",
  "Velocidade", "Agilidade", "Coordenação", "Equilíbrio", "Flexibilidade", "Precisão", "Skill", "Core",
];
// Na tela de edição, só os 3 últimos exercícios de cada dia ficam à vista; os anteriores ficam numa aba que se abre ao tocar
const LIMITE_VISIVEL = 3;
// Tira do começo da linha o que é quantidade ("40x ", "200 M ", "2-3 20 x ", "G1- ") e deixa só o nome do exercício
const PREFIXO_QTD = /^\s*(?:[A-Za-z]\d+\s*[-–.)]\s*)?(?:\d[\d.,\-–/']*\s*(?:[xX×]\s*)?(?:(?:km|min|seg|reps?|cal|m|s)\b\s*)?)*/i;
const limparNome = (t) => normalizarTexto(t).replace(/[^a-z0-9]+/g, " ").trim();

// Programação da semana atual dentro de uma pasta (ou null)
function acharProgramacaoDaSemana(programacoes, pasta) {
  const segunda = segundaDe();
  return programacoes.find((pr) => {
    const ref = dataRefProgramacao(pr);
    return mesmaPasta(pastaDe(pr), pasta) && ref && segundaDe(dataISOLocal(ref)) === segunda;
  }) || null;
}

// Último objetivo usado em cada exercício nas programações (para pré-preencher)
function construirMapaObjetivos(programacoes) {
  const mapa = {};
  [...programacoes]
    .sort((x, y) => (dataRefProgramacao(x) || 0) - (dataRefProgramacao(y) || 0))
    .forEach((pr) => pr.dias.forEach((d) => exerciciosDoDia(d).forEach((e) => {
      if (e.objetivo) mapa[limparNome(e.nome)] = e.objetivo;
    })));
  return mapa;
}

/* ---------- nomes parecidos (apelidos) e reconhecimento de exercícios ---------- */
const apelidosDe = (ex) => String(ex.apelidos || "").split(/[,;\n]/).map((a) => a.trim()).filter(Boolean);
const variantesDe = (ex) => [ex.nome, ...apelidosDe(ex)];

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
}
const simToken = (a, b) => 1 - levenshtein(a, b) / Math.max(a.length, b.length);
// 0 a 1: quanto dois nomes de exercício parecem ser a mesma coisa (palavra a palavra, tolera erros de escrita)
function similaridadeNomes(a, b) {
  const ta = limparNome(a).split(" ").filter(Boolean);
  const tb = limparNome(b).split(" ").filter(Boolean);
  if (!ta.length || !tb.length) return 0;
  const dir = (x, y) => x.reduce((soma, t) => soma + Math.max(...y.map((u) => simToken(t, u))), 0) / x.length;
  return Math.min(dir(ta, tb), dir(tb, ta));
}
function similaresNaBiblioteca(nome, biblioteca, limite = 2) {
  return biblioteca
    .map((ex) => ({ ex, s: Math.max(...variantesDe(ex).map((v) => similaridadeNomes(nome, v))) }))
    .filter((x) => x.s >= 0.7 && limparNome(x.ex.nome) !== limparNome(nome))
    .sort((x, y) => y.s - x.s)
    .slice(0, limite)
    .map((x) => x.ex);
}
// Lista de todos os nomes (e apelidos) da biblioteca, do maior para o menor, apontando para o nome principal
function indiceBiblioteca(biblioteca) {
  const lista = [];
  biblioteca.forEach((b) => variantesDe(b).forEach((v) => {
    const n = limparNome(v);
    if (n) lista.push({ nome: b.nome, n });
  }));
  return lista.sort((a, b) => b.n.length - a.n.length);
}
// aceita singular/plural ("squat" e "squats") quando o nome tem 4+ letras
const achaNoIndice = (indice, resto) =>
  indice.find((x) => [x.n, ...(x.n.length >= 4 ? [`${x.n}s`, x.n.replace(/s$/, "")] : [])].some((v) => resto.includes(` ${v} `)));

// Reconhece, no texto do treino, os exercícios que existem na biblioteca
function extrairExerciciosDoTreino(w, biblioteca, mapaObjetivos) {
  const fontes = [
    { texto: w.warmupGeral, padrao: "Aquecimento" },
    { texto: w.warmupEspecifico, padrao: "Aquecimento" },
    { texto: w.skill, padrao: "Skill" },
    ...(w.blocos || []).map((b) => ({ texto: b.conteudo, padrao: "" })),
  ];
  const indice = indiceBiblioteca(biblioteca);
  const vistos = new Set();
  const saida = [];
  fontes.forEach(({ texto, padrao }) => String(texto || "").split("\n").forEach((linha) => {
    const pre = (PREFIXO_QTD.exec(linha) || [""])[0];
    const resto = ` ${limparNome(linha.slice(pre.length))} `;
    if (resto.trim() === "") return;
    const achado = achaNoIndice(indice, resto);
    const canon = achado ? limparNome(achado.nome) : "";
    if (!achado || vistos.has(canon)) return;
    vistos.add(canon);
    saida.push({ nome: achado.nome, objetivo: padrao || mapaObjetivos[canon] || "" });
  }));
  return saida;
}

// Linhas do treino (que começam com quantidade) cujo exercício NÃO está na biblioteca: candidatos a cadastrar
const PALAVRAS_NAO_EXERCICIO = ["round", "rounds", "time cap", "timecap", "emom", "amrap", "rest", "descanso", "intensidade", "objetivo", "objetivos", "carga", "pausa", "min", "seg", "serie", "series"];
function limparCandidato(txt) {
  return String(txt || "").replace(/\([^)]*\)/g, " ").replace(/[.,;:!]+$/g, "").replace(/\s+/g, " ").trim();
}
function candidatosForaDaBiblioteca(textos, biblioteca, excluirChaves = new Set()) {
  const indice = indiceBiblioteca(biblioteca);
  const vistos = new Set();
  const saida = [];
  textos.forEach((texto) => String(texto || "").split("\n").forEach((linha) => {
    const pre = (PREFIXO_QTD.exec(linha) || [""])[0];
    if (!pre.trim()) return; // só linhas que começam com quantidade ("40x", "200 M", "G1-")
    const nome = limparCandidato(linha.slice(pre.length));
    const chave = limparNome(nome);
    if (nome.length < 3 || nome.length > 45 || /\d/.test(nome) || !chave) return;
    if (chave.split(" ").length > 6) return;
    if (PALAVRAS_NAO_EXERCICIO.some((pl) => ` ${chave} `.includes(` ${pl} `))) return;
    if (achaNoIndice(indice, ` ${chave} `)) return; // já está na biblioteca (ou é um nome parecido cadastrado)
    if (excluirChaves.has(chave) || vistos.has(chave)) return;
    vistos.add(chave);
    saida.push(nome);
  }));
  return saida;
}

function diasVazios() {
  return DIAS_SEMANA.map((dia) => ({ dia, exercicios: [] }));
}
const exerciciosDoDia = (d) => (Array.isArray(d.exercicios) ? d.exercicios : []);
const treinosDoDia = (d) => (Array.isArray(d.treinos) ? d.treinos : []);
const diaTemConteudo = (d) => exerciciosDoDia(d).length > 0 || treinosDoDia(d).length > 0;
// Junta textos iguais ignorando maiúsculas e acentos (para contar nos gráficos)
const normalizarTexto = (t) => String(t || "").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
// Antes, se a lista de dias salva não tivesse exatamente 7 itens, TODOS os exercícios eram descartados em silêncio
// (e sumiam das contagens). Agora cada dia é encaixado pelo nome (SEG, TER...) ou pela posição.
function normalizarDiasSalvos(dias) {
  if (!Array.isArray(dias) || dias.length === 0) return diasVazios();
  if (dias.length === DIAS_SEMANA.length) return dias;
  const saida = diasVazios();
  dias.forEach((d, i) => {
    let idx = DIAS_SEMANA.indexOf(normalizarTexto(d && d.dia).toUpperCase());
    if (idx < 0) idx = DIAS_SEMANA.findIndex((x) => normalizarTexto(x) === normalizarTexto(d && d.dia));
    if (idx < 0) idx = i;
    if (idx >= 0 && idx < saida.length && d) {
      saida[idx] = { ...saida[idx], ...d, dia: DIAS_SEMANA[idx], exercicios: [...exerciciosDoDia(saida[idx]), ...exerciciosDoDia(d)] };
    }
  });
  return saida;
}
const programacaoFromDb = (r) => ({
  id: r.id, nome: r.nome || "", destaque: !!r.destaque, descricao: r.descricao || "",
  semanaInicio: r.semana_inicio || "",
  pasta: r.pasta || "",
  dias: normalizarDiasSalvos(r.dias),
  criadoEm: r.criado_em, atualizadoEm: r.atualizado_em,
});
const programacaoToDb = (p) => ({ nome: p.nome || "", destaque: !!p.destaque, descricao: p.descricao || "",
  semana_inicio: p.semanaInicio || null,
  pasta: (p.pasta || "").trim(),
  dias: p.dias.map((d) => ({
    dia: d.dia,
    exercicios: exerciciosDoDia(d).map((e) => ({ nome: e.nome, objetivo: e.objetivo || "" })),
    treinos: treinosDoDia(d), // treinos marcados como "executado hoje" naquele dia
  })),
});

