// Trecho automático do início do texto (usado quando o estudo não tem resumo escrito)
function trechoDe(texto, max = 320) {
  const t = (texto || "").replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  const corte = t.slice(0, max);
  const fimFrase = Math.max(corte.lastIndexOf(". "), corte.lastIndexOf("; "));
  if (fimFrase > 120) return corte.slice(0, fimFrase + 1);
  return `${corte.slice(0, corte.lastIndexOf(" "))}…`;
}

// Se colunas novas (pasta, semana_inicio, descricao) ainda não existem no banco, tenta salvar sem elas
async function gravarProgramacao(executar, payload) {
  const { pasta, ...semPasta } = payload;
  const { semana_inicio, ...semPastaSemData } = semPasta;
  const { descricao, ...minimo } = semPastaSemData;
  let data = null;
  let error = null;
  for (const tentativa of [payload, semPasta, semPastaSemData, minimo]) {
    ({ data, error } = await executar(tentativa));
    if (!error) break;
  }
  if (error) { console.error(error); return null; }
  return programacaoFromDb(data);
}
async function inserirProgramacaoDb(p) {
  const agora = new Date().toISOString();
  const payload = { ...programacaoToDb(p), criado_em: agora, atualizado_em: agora };
  return gravarProgramacao((d) => supabase.from("programacoes_semanais").insert(d).select().single(), payload);
}
async function atualizarProgramacaoDb(id, p) {
  const payload = { ...programacaoToDb(p), atualizado_em: new Date().toISOString() };
  return gravarProgramacao((d) => supabase.from("programacoes_semanais").update(d).eq("id", id).select().single(), payload);
}
