async function fetchAvaliacaoConfig() {
  let { data, error } = await supabase.from("avaliacao_config").select("perguntas, termos").eq("id", 1).maybeSingle();
  if (error) { // coluna "termos" pode ainda não existir: lê só as perguntas
    ({ data, error } = await supabase.from("avaliacao_config").select("perguntas").eq("id", 1).maybeSingle());
  }
  if (error) { console.error(error); return { perguntas: PERGUNTAS_PADRAO, termos: "" }; }
  const perguntas = data && Array.isArray(data.perguntas) ? data.perguntas : PERGUNTAS_PADRAO;
  return { perguntas, termos: (data && data.termos) || "" };
}
async function salvarAvaliacaoTermosDb(senha, termos) {
  const { error } = await supabase.rpc("avaliacao_salvar_termos", { p_senha: senha, p_termos: termos });
  if (error) console.error(error);
  return !error;
}
async function salvarAvaliacaoPerguntasDb(senha, perguntas) {
  const { error } = await supabase.rpc("avaliacao_salvar_perguntas", { p_senha: senha, p_perguntas: perguntas });
  if (error) console.error(error);
  return !error;
}
// Devolve a data/hora oficial do registro (gerada no servidor), ou null se falhar.
async function enviarAvaliacaoDb(nome, respostas) {
  const { data, error } = await supabase.rpc("avaliacao_enviar", { p_nome: nome, p_respostas: respostas });
  if (error) { console.error(error); return null; }
  return data;
}
