/* =================================================================
   HYBRID CANTIL
   Pasta compartilhada: um link + um código único para todos.
   Só enxerga esta área (não abre nada do restante do app).
   Dados ficam em tabelas próprias, acessadas só por funções (RPC)
   que exigem o código. Rode hybrid_cantil.sql no Supabase.
================================================================= */

const NOME_PASTA_HYBRID = "HYBRID CANTIL";
const DESCRICAO_PASTA_HYBRID =
  "Resultados individuais e por equipe, tempo de cada prova, treinos específicos, métricas de corrida e simulados de HYROX";
const CHAVE_HYBRID_SESSAO = "cantil_hybrid_sessao";
const EQUIPE_PADRAO_HYBRID = "CANTIL";
const TIPOS_CORRIDA = ["Rodagem", "Tiro / Intervalado", "Longão", "Teste / Prova", "Recuperação"];
const CATEGORIAS_HYROX = ["Open", "Pro", "Dupla"];
// Ordem oficial de uma prova HYROX: 8 x (1 km de corrida + 1 estação)
const SEGMENTOS_HYROX = [
  "Corrida 1", "SkiErg 1000 m", "Corrida 2", "Sled Push 50 m", "Corrida 3", "Sled Pull 50 m",
  "Corrida 4", "Burpee Broad Jump 80 m", "Corrida 5", "Remo 1000 m", "Corrida 6", "Farmers Carry 200 m",
  "Corrida 7", "Sandbag Lunges 100 m", "Corrida 8", "Wall Balls 100 reps",
];
const ehCorridaHyrox = (i) => i % 2 === 0;

function buildShareUrlHybrid() {
  const { origin, pathname } = window.location;
  return `${origin}${pathname}#/hybrid`;
}
function parseHashHybrid() {
  return window.location.hash.startsWith("#/hybrid");
}
const SOMENTE_HYBRID = (() => {
  // Deploy exclusivo: defina VITE_SOMENTE_HYBRID=true e o app inteiro vira só a pasta HYBRID CANTIL
  try { return String(import.meta.env.VITE_SOMENTE_HYBRID) === "true"; } catch { return false; }
})();

/* ---------------------------- tempo / pace ---------------------------- */
// Aceita "mm:ss", "h:mm:ss" ou só segundos. Devolve segundos ou null.
function parseTempo(txt) {
  const s = String(txt ?? "").trim().replace(",", ".");
  if (!s) return null;
  const partes = s.split(":");
  if (partes.length > 3 || partes.some((p) => p.trim() === "" || isNaN(Number(p)) || Number(p) < 0)) return null;
  return partes.map(Number).reduce((acc, x) => acc * 60 + x, 0);
}
// Digite só números: 435 -> 4:35 · 3800 -> 38:00 · 13800 -> 1:38:00 (apagar volta um dígito)
function mascaraTempo(novo) {
  const d = String(novo || "").replace(/\D/g, "").replace(/^0+/, "").slice(-6);
  if (!d) return "";
  const ss = d.slice(-2).padStart(2, "0");
  const mm = d.slice(-4, -2);
  const hh = d.slice(-6, -4);
  if (hh) return `${parseInt(hh, 10)}:${mm.padStart(2, "0")}:${ss}`;
  return `${parseInt(mm || "0", 10)}:${ss}`;
}
function TempoInput({ value, onChange, placeholder = "mm:ss", style }) {
  return (
    <TextInput
      inputMode="numeric"
      value={value}
      placeholder={placeholder}
      onChange={(e) => onChange(mascaraTempo(e.target.value))}
      style={style}
    />
  );
}
const DicaTempo = () => <div style={{ fontSize: 11.5, color: "#8E8F96", marginTop: -6, marginBottom: 12 }}>Digite só os números: 1245 vira 12:45 · 13800 vira 1:38:00</div>;

function fmtTempo(seg) {
  if (seg == null || isNaN(seg)) return "—";
  const t = Math.round(seg);
  const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
  return h > 0 ? `${h}:${pad2(m)}:${pad2(s)}` : `${m}:${pad2(s)}`;
}
const fmtPace = (segKm) => (segKm == null ? "—" : `${fmtTempo(segKm)}/km`);
const fmtKm = (km) => `${(Math.round(km * 100) / 100).toLocaleString("pt-BR")} km`;
const dataCurtaHy = (iso) => (iso && iso.length >= 10 ? `${iso.slice(8, 10)}/${iso.slice(5, 7)}` : "");

/* ---------------------------- banco (RPC com código) ---------------------------- */
const registroHybridFromDb = (r) => ({
  id: r.id, tipo: r.tipo, atleta: r.atleta || "", equipe: r.equipe || EQUIPE_PADRAO_HYBRID, nome: r.nome || "",
  data: (r.data || "").slice(0, 10), dados: r.dados || {}, criadoEm: r.criado_em,
});
async function hybridListarDb(codigo) {
  const { data, error } = await supabase.rpc("hybrid_listar", { p_codigo: codigo });
  if (error) {
    console.error(error);
    return { erro: String(error.message || "").includes("codigo_invalido") ? "codigo" : "rede" };
  }
  return { dados: (data || []).map(registroHybridFromDb) };
}
async function hybridSalvarDb(codigo, r) {
  const { data, error } = await supabase.rpc("hybrid_salvar", {
    p_codigo: codigo, p_tipo: r.tipo, p_atleta: r.atleta, p_equipe: r.equipe, p_nome: r.nome, p_data: r.data, p_dados: r.dados,
  });
  if (error) { console.error(error); return null; }
  return registroHybridFromDb(data);
}
async function hybridExcluirDb(codigo, id, atleta, senha) {
  const { data, error } = await supabase.rpc("hybrid_excluir", { p_codigo: codigo, p_id: id, p_atleta: atleta, p_senha: senha || "" });
  if (error) { console.error(error); return false; }
  return !!data;
}
async function hybridDefinirCodigoDb(senha, codigo) {
  const { data, error } = await supabase.rpc("hybrid_definir_codigo", { p_senha: senha, p_codigo: codigo });
  if (error) { console.error(error); return false; }
  return !!data;
}
function lerSessaoHybrid() {
  try { return JSON.parse(window.localStorage.getItem(CHAVE_HYBRID_SESSAO) || "null"); } catch { return null; }
}
function salvarSessaoHybrid(s) {
  try {
    if (s) window.localStorage.setItem(CHAVE_HYBRID_SESSAO, JSON.stringify(s));
    else window.localStorage.removeItem(CHAVE_HYBRID_SESSAO);
  } catch { /* ignora */ }
}

/* ---------------------------- métricas ---------------------------- */
// Workouts com tempo (FOR TIME...) = menor é melhor. AMRAP = mais reps é melhor.
function valorWorkout(r) {
  const d = r.dados || {};
  if (d.formato === "AMRAP") return typeof d.reps === "number" ? d.reps : null;
  return typeof d.tempoSeg === "number" ? d.tempoSeg : null;
}
const fmtWorkout = (v, formato) => (formato === "AMRAP" ? `${v} reps` : fmtTempo(v));
const valorCorridaPace = (r) => (typeof r.dados?.paceSeg === "number" ? r.dados.paceSeg : null);
const valorHyrox = (r) => (r.dados?.completo && typeof r.dados.totalSeg === "number" ? r.dados.totalSeg : null);

function melhorPorAtleta(regs, extrair, menorMelhor) {
  const mapa = {};
  regs.forEach((r) => {
    const v = extrair(r);
    if (v == null) return;
    const k = normalizarTexto(r.atleta);
    const atual = mapa[k];
    if (!atual || (menorMelhor ? v < atual.valor : v > atual.valor)) mapa[k] = { rotulo: r.atleta, sub: r.equipe, equipe: r.equipe, valor: v };
  });
  return Object.values(mapa).sort((a, b) => (menorMelhor ? a.valor - b.valor : b.valor - a.valor));
}
function somaPorAtleta(regs, extrair) {
  const mapa = {};
  regs.forEach((r) => {
    const v = extrair(r);
    if (v == null) return;
    const k = normalizarTexto(r.atleta);
    if (!mapa[k]) mapa[k] = { rotulo: r.atleta, sub: r.equipe, equipe: r.equipe, valor: 0 };
    mapa[k].valor += v;
  });
  return Object.values(mapa).sort((a, b) => b.valor - a.valor);
}
// Junta os atletas por equipe (média ou soma)
function agruparEquipes(linhas, modo, menorMelhor) {
  const g = {};
  linhas.forEach((l) => {
    const k = normalizarTexto(l.equipe) || "sem equipe";
    if (!g[k]) g[k] = { rotulo: l.equipe || "Sem equipe", valores: [] };
    g[k].valores.push(l.valor);
  });
  return Object.values(g)
    .map((e) => ({
      rotulo: e.rotulo,
      sub: `${e.valores.length} atleta${e.valores.length === 1 ? "" : "s"}`,
      valor: modo === "soma" ? e.valores.reduce((a, b) => a + b, 0) : e.valores.reduce((a, b) => a + b, 0) / e.valores.length,
    }))
    .sort((a, b) => (menorMelhor ? a.valor - b.valor : b.valor - a.valor));
}
const media = (arr) => (arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null);

/* ---------------------------- gráficos ---------------------------- */
const cardHy = { background: "#1A1B1E", border: "1px solid #26272B", borderRadius: 12, padding: "14px 16px", marginBottom: 12 };
const chipHy = (ativo) => ({
  flexShrink: 0, cursor: "pointer", whiteSpace: "nowrap", borderRadius: 999, padding: "7px 13px", fontSize: 12.5,
  fontWeight: ativo ? 800 : 600, background: ativo ? "#E4DE00" : "#1C1D20", color: ativo ? "#0A0A0A" : "#B9BABF",
  border: `1px solid ${ativo ? "#E4DE00" : "#3A3B40"}`,
});

function RankingBarras({ linhas, formatar, menorMelhor = true, destaque = "", vazio = "Sem resultados ainda." }) {
  if (!linhas.length) return <EmptyState text={vazio} />;
  const max = Math.max(...linhas.map((l) => l.valor));
  const melhor = linhas[0].valor;
  return (
    <div>
      {linhas.map((l, i) => {
        const eu = destaque && normalizarTexto(l.rotulo) === normalizarTexto(destaque);
        const larg = menorMelhor ? (l.valor > 0 ? (melhor / l.valor) * 100 : 100) : max > 0 ? (l.valor / max) * 100 : 0;
        return (
          <div key={l.rotulo + i} style={{ marginTop: i ? 10 : 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ width: 22, fontSize: 11, color: i === 0 ? "#E4DE00" : "#8E8F96", fontWeight: 800 }}>{i + 1}º</span>
              <span style={{ flex: 1, minWidth: 0, fontSize: 13, color: eu ? "#E4DE00" : "#F1EFE9", fontWeight: 700 }}>
                {l.rotulo}{l.sub ? <span style={{ color: "#8E8F96", fontWeight: 500, fontSize: 11 }}> · {l.sub}</span> : null}
              </span>
              <span style={{ fontSize: 13, fontWeight: 800, color: "#E4DE00", fontFamily: "'JetBrains Mono', monospace" }}>{formatar(l.valor)}</span>
            </div>
            <div style={{ height: 7, background: "#26272B", borderRadius: 4, marginTop: 5, overflow: "hidden" }}>
              <div style={{ width: `${Math.max(3, larg)}%`, height: "100%", background: eu ? "#E4DE00" : i === 0 ? "#E4DE00" : "#6E6C1A" }} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

function LinhaEvolucao({ pontos, formatar, menorMelhor = true }) {
  if (!pontos.length) return <EmptyState text="Sem registros para mostrar." />;
  const pts = [...pontos].sort((a, b) => (a.data || "").localeCompare(b.data || ""));
  const W = 320, H = 150, pl = 14, pr = 14, pt = 22, pb = 24;
  const vals = pts.map((p) => p.valor);
  let mn = Math.min(...vals), mx = Math.max(...vals);
  if (mn === mx) { mn -= 1; mx += 1; }
  const x = (i) => (pts.length === 1 ? W / 2 : pl + (i * (W - pl - pr)) / (pts.length - 1));
  const y = (v) => { const f = (v - mn) / (mx - mn); return pt + (menorMelhor ? f : 1 - f) * (H - pt - pb); };
  const idxMelhor = vals.indexOf(menorMelhor ? Math.min(...vals) : Math.max(...vals));
  const mostrar = new Set([0, pts.length - 1, idxMelhor]);
  const linha = pts.map((p, i) => `${x(i)},${y(p.valor)}`).join(" ");
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto", display: "block" }}>
      <line x1={pl} x2={W - pr} y1={H - pb} y2={H - pb} stroke="#26272B" />
      {pts.length > 1 && <polyline points={linha} fill="none" stroke="#E4DE00" strokeWidth="2" strokeLinejoin="round" />}
      {pts.map((p, i) => (
        <g key={i}>
          <circle cx={x(i)} cy={y(p.valor)} r={i === idxMelhor ? 5 : 3.5} fill={i === idxMelhor ? "#E4DE00" : "#0A0A0A"} stroke="#E4DE00" strokeWidth="2" />
          {mostrar.has(i) && (
            <text x={x(i)} y={y(p.valor) - 9} textAnchor="middle" fontSize="10" fontWeight="700" fill={i === idxMelhor ? "#E4DE00" : "#B9BABF"}>{formatar(p.valor)}</text>
          )}
        </g>
      ))}
      <text x={pl} y={H - 8} fontSize="9.5" fill="#8E8F96">{dataCurtaHy(pts[0].data)}</text>
      {pts.length > 1 && <text x={W - pr} y={H - 8} textAnchor="end" fontSize="9.5" fill="#8E8F96">{dataCurtaHy(pts[pts.length - 1].data)}</text>}
    </svg>
  );
}

const CORES_HY = ["#E4DE00", "#4B9EEA", "#FF8A3D", "#4CAF6D", "#9B6BD9", "#E6483F", "#2EC4B6", "#F78FB3"];
// Agrupa registros em séries (por atleta ou por equipe), por data
function montarSeries(items, { porEquipe = false, cumulativo = false } = {}) {
  const g = {};
  items.forEach((it) => {
    const k = porEquipe ? normalizarTexto(it.equipe) || "sem equipe" : normalizarTexto(it.atleta);
    if (!g[k]) g[k] = { rotulo: porEquipe ? it.equipe || "Sem equipe" : it.atleta, porData: {} };
    (g[k].porData[it.data] = g[k].porData[it.data] || []).push(it.valor);
  });
  return Object.values(g).map((s) => {
    let pontos = Object.keys(s.porData).sort().map((d) => ({
      data: d, valor: cumulativo ? s.porData[d].reduce((x, y) => x + y, 0) : media(s.porData[d]),
    }));
    if (cumulativo) { let acc = 0; pontos = pontos.map((p) => { acc += p.valor; return { ...p, valor: acc }; }); }
    return { rotulo: s.rotulo, pontos };
  });
}

function LinhasMulti({ series, formatar, menorMelhor = true, destaque = "", rotuloX = dataCurtaHy }) {
  let lista = series.filter((s) => s.pontos.length);
  if (!lista.length) return <EmptyState text="Sem registros para mostrar neste período." />;
  lista = lista.sort((a, b) => b.pontos.length - a.pontos.length || a.rotulo.localeCompare(b.rotulo, "pt-BR"));
  const eu = lista.find((s) => destaque && normalizarTexto(s.rotulo) === normalizarTexto(destaque));
  lista = lista.slice(0, 8);
  if (eu && !lista.includes(eu)) lista[lista.length - 1] = eu;
  const W = 320, H = 190, pl = 12, pr = 12, pt = 14, pb = 26;
  const tempo = (d) => new Date(d + "T12:00:00").getTime();
  const todos = lista.flatMap((s) => s.pontos);
  const tmin = Math.min(...todos.map((p) => tempo(p.data))), tmax = Math.max(...todos.map((p) => tempo(p.data)));
  let mn = Math.min(...todos.map((p) => p.valor)), mx = Math.max(...todos.map((p) => p.valor));
  if (mn === mx) { mn -= 1; mx += 1; }
  const x = (d) => (tmax === tmin ? W / 2 : pl + ((tempo(d) - tmin) / (tmax - tmin)) * (W - pl - pr));
  const y = (v) => { const f = (v - mn) / (mx - mn); return pt + (menorMelhor ? f : 1 - f) * (H - pt - pb); };
  const dMin = todos.map((p) => p.data).sort()[0], dMax = todos.map((p) => p.data).sort().slice(-1)[0];
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto", display: "block" }}>
        <line x1={pl} x2={W - pr} y1={H - pb} y2={H - pb} stroke="#2E2F34" />
        <text x={pl} y={pt - 3} fontSize="9.5" fill="#8E8F96">{formatar(menorMelhor ? mn : mx)}</text>
        <text x={pl} y={H - pb - 4} fontSize="9.5" fill="#8E8F96">{formatar(menorMelhor ? mx : mn)}</text>
        {lista.map((s, si) => {
          const cor = CORES_HY[si % CORES_HY.length];
          const souEu = s === eu;
          return (
            <g key={s.rotulo}>
              {s.pontos.length > 1 && <polyline points={s.pontos.map((p) => `${x(p.data)},${y(p.valor)}`).join(" ")} fill="none" stroke={cor} strokeWidth={souEu ? 3 : 2} strokeLinejoin="round" opacity={eu && !souEu ? 0.75 : 1} />}
              {s.pontos.map((p, i) => <circle key={i} cx={x(p.data)} cy={y(p.valor)} r={souEu ? 4 : 3} fill={cor} />)}
            </g>
          );
        })}
        <text x={pl} y={H - 8} fontSize="9.5" fill="#8E8F96">{rotuloX(dMin)}</text>
        {dMax !== dMin && <text x={W - pr} y={H - 8} textAnchor="end" fontSize="9.5" fill="#8E8F96">{rotuloX(dMax)}</text>}
      </svg>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 14px", marginTop: 10 }}>
        {lista.map((s, si) => {
          const vals = s.pontos.map((p) => p.valor);
          const melhor = menorMelhor ? Math.min(...vals) : Math.max(...vals);
          return (
            <span key={s.rotulo} style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, color: "#E6E4DE" }}>
              <span style={{ width: 10, height: 10, borderRadius: "50%", background: CORES_HY[si % CORES_HY.length] }} />
              <b>{s.rotulo}</b> <span style={{ color: "#8E8F96" }}>{formatar(melhor)}</span>
            </span>
          );
        })}
      </div>
    </div>
  );
}

function ColunasEvolucao({ pontos, formatar, menorMelhor = true }) {
  if (!pontos.length) return <EmptyState text="Sem registros para mostrar." />;
  const pts = [...pontos].sort((a, b) => (a.data || "").localeCompare(b.data || "")).slice(-14);
  const W = 320, H = 170, pt = 22, pb = 26;
  const vals = pts.map((p) => p.valor);
  const max = Math.max(...vals, 1);
  const idxMelhor = vals.indexOf(menorMelhor ? Math.min(...vals) : Math.max(...vals));
  const passo = (W - 20) / pts.length;
  const bw = Math.min(30, passo * 0.62);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto", display: "block" }}>
      <line x1={8} x2={W - 8} y1={H - pb} y2={H - pb} stroke="#2E2F34" />
      {pts.map((p, i) => {
        const h = Math.max(3, (p.valor / max) * (H - pt - pb));
        const cx = 10 + passo * i + passo / 2;
        const mostrarValor = pts.length <= 8 || i === idxMelhor || i === pts.length - 1;
        return (
          <g key={i}>
            <rect x={cx - bw / 2} y={H - pb - h} width={bw} height={h} rx="3" fill={i === idxMelhor ? "#E4DE00" : "#6E6C1A"} />
            {mostrarValor && <text x={cx} y={H - pb - h - 5} textAnchor="middle" fontSize="9.5" fontWeight="700" fill={i === idxMelhor ? "#E4DE00" : "#D0D1D6"}>{formatar(p.valor)}</text>}
            {(pts.length <= 8 || i % 2 === 0) && <text x={cx} y={H - 9} textAnchor="middle" fontSize="9" fill="#8E8F96">{dataCurtaHy(p.data)}</text>}
          </g>
        );
      })}
    </svg>
  );
}
function GraficoEvolucao({ tipo, ...props }) {
  return tipo === "barras" ? <ColunasEvolucao {...props} /> : <LinhaEvolucao {...props} />;
}

function BlocoHy({ titulo, ajuda, icone, children }) {
  return (
    <div style={cardHy}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        {icone}
        <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 16, color: "#FFFFFF", letterSpacing: "0.05em", textTransform: "uppercase" }}>{titulo}</span>
      </div>
      {ajuda && <div style={{ fontSize: 11.5, color: "#8E8F96", margin: "4px 0 12px", lineHeight: 1.4 }}>{ajuda}</div>}
      {!ajuda && <div style={{ height: 10 }} />}
      {children}
    </div>
  );
}
function MiniStat({ rotulo, valor }) {
  return (
    <div style={{ flex: 1, minWidth: 0, background: "#1C1D20", border: "1px solid #2E2F34", borderRadius: 10, padding: "9px 10px" }}>
      <div style={{ fontSize: 10.5, color: "#8E8F96", fontWeight: 600 }}>{rotulo}</div>
      <div style={{ fontSize: 15, color: "#F1EFE9", fontWeight: 800, marginTop: 3, fontFamily: "'JetBrains Mono', monospace" }}>{valor}</div>
    </div>
  );
}

/* ---------------------------- aba RESULTADOS (gráficos) ---------------------------- */
function ResultadosHybrid({ registros: todosRegistros, sessao }) {
  const [modo, setModo] = useState("equipe"); // equipe | individual
  const [tema, setTema] = useState("workouts"); // workouts | corrida | hyrox
  const [agrupar, setAgrupar] = useState("atletas"); // atletas | equipes
  const [workoutKey, setWorkoutKey] = useState("");
  const [metricaCorrida, setMetricaCorrida] = useState("km");
  const [atletaSel, setAtletaSel] = useState(sessao.atleta);
  const [grafico, setGrafico] = useState("barras"); // barras | linha
  const [periodo, setPeriodo] = useState({ modo: "tudo", de: "", ate: "", mesDe: "", mesAte: "" }); // tudo | dias | meses

  const passaPeriodo = (r) => {
    if (periodo.modo === "dias") {
      if (periodo.de && r.data < periodo.de) return false;
      if (periodo.ate && r.data > periodo.ate) return false;
    } else if (periodo.modo === "meses") {
      const m = r.data.slice(0, 7);
      if (periodo.mesDe && m < periodo.mesDe) return false;
      if (periodo.mesAte && m > periodo.mesAte) return false;
    }
    return true;
  };
  const registros = todosRegistros.filter(passaPeriodo);
  const hojeD = new Date();
  const mesISO = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}`;
  const atalhoPeriodo = (tipo) => {
    if (tipo === "mes") setPeriodo({ modo: "meses", de: "", ate: "", mesDe: mesISO(hojeD), mesAte: mesISO(hojeD) });
    else if (tipo === "passado") { const d = new Date(hojeD.getFullYear(), hojeD.getMonth() - 1, 1); setPeriodo({ modo: "meses", de: "", ate: "", mesDe: mesISO(d), mesAte: mesISO(d) }); }
    else { const ini = new Date(hojeD.getFullYear(), hojeD.getMonth(), hojeD.getDate() - 29); setPeriodo({ modo: "dias", de: dataISOLocal(ini), ate: dataISOLocal(hojeD), mesDe: "", mesAte: "" }); }
  };

  const atletas = [...new Map(registros.map((r) => [normalizarTexto(r.atleta), r.atleta])).values()]
    .sort((a, b) => a.localeCompare(b, "pt-BR"));
  const atletaAtivo = atletas.find((a) => normalizarTexto(a) === normalizarTexto(atletaSel)) || atletas[0] || "";
  const ehAtleta = (r) => normalizarTexto(r.atleta) === normalizarTexto(atletaAtivo);
  const doTipo = (...t) => registros.filter((r) => t.includes(r.tipo));
  const temEquipes = new Set(registros.map((r) => normalizarTexto(r.equipe))).size > 1;
  const verEquipes = agrupar === "equipes" && temEquipes;

  const kmTotal = doTipo("corrida").reduce((s, r) => s + (r.dados?.km || 0), 0);
  const resumo = [
    { rotulo: "Atletas", valor: atletas.length },
    { rotulo: "Registros", valor: registros.length },
    { rotulo: "Km corridos", valor: Math.round(kmTotal) },
    { rotulo: "Simulados", valor: doTipo("hyrox").length },
  ];

  const blocoPeriodo = (
    <div style={{ ...cardHy, padding: "12px 14px" }}>
      <div style={{ fontSize: 12, fontWeight: 700, color: "#A9AAB1", marginBottom: 8, display: "flex", alignItems: "center", gap: 6 }}>
        <CalendarDays size={14} color="#E4DE00" /> Período dos gráficos
      </div>
      <div style={{ display: "flex", gap: 6, overflowX: "auto", marginBottom: 8 }}>
        {[["tudo", "Tudo"], ["dias", "De dia a dia"], ["meses", "De mês a mês"]].map(([v, l]) => (
          <button key={v} onClick={() => setPeriodo({ ...periodo, modo: v })} style={chipHy(periodo.modo === v)}>{l}</button>
        ))}
      </div>
      {periodo.modo === "dias" && (
        <div style={{ display: "flex", gap: 10 }}>
          <div style={{ flex: 1 }}><Field label="Do dia"><TextInput type="date" value={periodo.de} onChange={(e) => setPeriodo({ ...periodo, de: e.target.value })} /></Field></div>
          <div style={{ flex: 1 }}><Field label="Até o dia"><TextInput type="date" value={periodo.ate} onChange={(e) => setPeriodo({ ...periodo, ate: e.target.value })} /></Field></div>
        </div>
      )}
      {periodo.modo === "meses" && (
        <>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Do mês"><TextInput type="month" value={periodo.mesDe} onChange={(e) => setPeriodo({ ...periodo, mesDe: e.target.value })} /></Field></div>
            <div style={{ flex: 1 }}><Field label="Até o mês"><TextInput type="month" value={periodo.mesAte} onChange={(e) => setPeriodo({ ...periodo, mesAte: e.target.value })} /></Field></div>
          </div>
          <div style={{ fontSize: 11.5, color: "#8E8F96", marginTop: -4, marginBottom: 8 }}>Para ver um mês só, escolha o mesmo mês nos dois campos.</div>
        </>
      )}
      <div style={{ display: "flex", gap: 6, overflowX: "auto" }}>
        <button onClick={() => atalhoPeriodo("mes")} style={chipHy(false)}>Este mês</button>
        <button onClick={() => atalhoPeriodo("passado")} style={chipHy(false)}>Mês passado</button>
        <button onClick={() => atalhoPeriodo("30")} style={chipHy(false)}>Últimos 30 dias</button>
      </div>
      {periodo.modo !== "tudo" && <div style={{ fontSize: 11.5, color: "#8E8F96", marginTop: 8 }}>Mostrando {registros.length} de {todosRegistros.length} registros</div>}
    </div>
  );

  const segmentoToggle = (valor, set, opcoes) => (
    <div style={{ display: "flex", gap: 6, overflowX: "auto", marginBottom: 12 }}>
      {opcoes.map(([v, l]) => <button key={v} onClick={() => set(v)} style={chipHy(valor === v)}>{l}</button>)}
    </div>
  );

  /* ---- workouts ---- */
  const regsW = doTipo("prova", "treino");
  const nomesW = {};
  regsW.forEach((r) => {
    const k = normalizarTexto(r.nome);
    if (!k) return;
    if (!nomesW[k]) nomesW[k] = { chave: k, nome: r.nome, n: 0, formato: r.dados?.formato || "FOR TIME" };
    nomesW[k].n++;
  });
  const listaW = Object.values(nomesW).sort((a, b) => b.n - a.n || a.nome.localeCompare(b.nome, "pt-BR"));
  const wAtivo = listaW.find((w) => w.chave === workoutKey) || listaW[0];
  const regsDoW = wAtivo ? regsW.filter((r) => normalizarTexto(r.nome) === wAtivo.chave) : [];
  const menorW = wAtivo ? wAtivo.formato !== "AMRAP" : true;
  const fmtW = (v) => fmtWorkout(v, wAtivo?.formato);

  /* ---- corrida ---- */
  const regsC = doTipo("corrida");
  /* ---- hyrox ---- */
  const regsH = doTipo("hyrox");

  const renderWorkouts = () => {
    if (!wAtivo) return <EmptyState text="Cadastre workouts nas abas Provas ou Específico para ver os gráficos." />;
    const seletor = (
      <Select value={wAtivo.chave} onChange={(e) => setWorkoutKey(e.target.value)} style={{ marginBottom: 12 }}>
        {listaW.map((w) => <option key={w.chave} value={w.chave}>{w.nome} ({w.n})</option>)}
      </Select>
    );
    if (modo === "equipe") {
      let linhas = melhorPorAtleta(regsDoW, valorWorkout, menorW);
      const mediaGeral = media(linhas.map((l) => l.valor));
      if (verEquipes) linhas = agruparEquipes(linhas, "media", menorW);
      return (
        <BlocoHy titulo={verEquipes ? "Ranking por equipe" : "Ranking da equipe"} icone={<Users size={18} color="#E4DE00" />}
          ajuda={verEquipes ? "Média do melhor resultado de cada atleta, por equipe." : "Melhor resultado de cada atleta neste workout."}>
          {seletor}
          {grafico === "linha"
            ? <LinhasMulti series={montarSeries(regsDoW.map((r) => ({ atleta: r.atleta, equipe: r.equipe, data: r.data, valor: valorWorkout(r) })).filter((i) => i.valor != null), { porEquipe: verEquipes })} formatar={fmtW} menorMelhor={menorW} destaque={verEquipes ? "" : sessao.atleta} />
            : <RankingBarras linhas={linhas} formatar={fmtW} menorMelhor={menorW} destaque={sessao.atleta} />}
          {mediaGeral != null && <div style={{ marginTop: 12, fontSize: 12, color: "#9A9A94" }}>Média da equipe: <b style={{ color: "#F1EFE9" }}>{fmtW(mediaGeral)}</b></div>}
        </BlocoHy>
      );
    }
    const meus = regsDoW.filter(ehAtleta);
    const pontos = meus.map((r) => ({ data: r.data, valor: valorWorkout(r) })).filter((p) => p.valor != null);
    const valores = pontos.map((p) => p.valor);
    const melhorV = valores.length ? (menorW ? Math.min(...valores) : Math.max(...valores)) : null;
    const ordenados = [...pontos].sort((a, b) => a.data.localeCompare(b.data));
    const ultimo = ordenados.length ? ordenados[ordenados.length - 1].valor : null;
    const mediaEq = media(melhorPorAtleta(regsDoW, valorWorkout, menorW).map((l) => l.valor));
    return (
      <BlocoHy titulo="Evolução individual" icone={<BarChart3 size={18} color="#E4DE00" />} ajuda="Como o atleta evoluiu neste workout ao longo do tempo (ponto cheio = melhor marca).">
        {seletor}
        <GraficoEvolucao tipo={grafico} pontos={pontos} formatar={fmtW} menorMelhor={menorW} />
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <MiniStat rotulo="Melhor" valor={melhorV != null ? fmtW(melhorV) : "—"} />
          <MiniStat rotulo="Último" valor={ultimo != null ? fmtW(ultimo) : "—"} />
          <MiniStat rotulo="Média equipe" valor={mediaEq != null ? fmtW(mediaEq) : "—"} />
        </div>
      </BlocoHy>
    );
  };

  const renderCorrida = () => {
    if (!regsC.length) return <EmptyState text="Cadastre corridas na aba Corrida para ver os gráficos." />;
    if (modo === "equipe") {
      const porKm = metricaCorrida === "km";
      let linhas = porKm
        ? somaPorAtleta(regsC, (r) => (typeof r.dados?.km === "number" ? r.dados.km : null))
        : melhorPorAtleta(regsC.filter((r) => (r.dados?.km || 0) >= 1), valorCorridaPace, true);
      if (verEquipes) linhas = agruparEquipes(linhas, porKm ? "soma" : "media", !porKm);
      return (
        <BlocoHy titulo={verEquipes ? "Corrida por equipe" : "Corrida da equipe"} icone={<Activity size={18} color="#E4DE00" />}
          ajuda={porKm ? "Quilômetros acumulados por atleta." : "Melhor pace (min/km) de cada atleta, em corridas de 1 km ou mais."}>
          {segmentoToggle(metricaCorrida, setMetricaCorrida, [["km", "Km total"], ["pace", "Melhor pace"]])}
          {grafico === "linha"
            ? <LinhasMulti
                series={montarSeries(
                  (porKm ? regsC.map((r) => ({ ...r, v: typeof r.dados?.km === "number" ? r.dados.km : null })) : regsC.filter((r) => (r.dados?.km || 0) >= 1).map((r) => ({ ...r, v: valorCorridaPace(r) })))
                    .filter((r) => r.v != null).map((r) => ({ atleta: r.atleta, equipe: r.equipe, data: r.data, valor: r.v })),
                  { porEquipe: verEquipes, cumulativo: porKm })}
                formatar={porKm ? fmtKm : fmtTempo} menorMelhor={!porKm} destaque={verEquipes ? "" : sessao.atleta} />
            : <RankingBarras linhas={linhas} formatar={porKm ? fmtKm : fmtPace} menorMelhor={!porKm} destaque={sessao.atleta} />}
        </BlocoHy>
      );
    }
    const meus = regsC.filter(ehAtleta);
    const pontos = meus.filter((r) => valorCorridaPace(r) != null).map((r) => ({ data: r.data, valor: valorCorridaPace(r) }));
    const kmAt = meus.reduce((s, r) => s + (r.dados?.km || 0), 0);
    const paces = pontos.map((p) => p.valor);
    return (
      <BlocoHy titulo="Evolução do pace" icone={<Activity size={18} color="#E4DE00" />} ajuda="Pace médio de cada corrida (quanto mais alto no gráfico, mais rápido).">
        <GraficoEvolucao tipo={grafico} pontos={pontos} formatar={fmtTempo} menorMelhor />
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <MiniStat rotulo="Corridas" valor={meus.length} />
          <MiniStat rotulo="Km total" valor={fmtKm(kmAt)} />
          <MiniStat rotulo="Melhor pace" valor={paces.length ? fmtPace(Math.min(...paces)) : "—"} />
        </div>
      </BlocoHy>
    );
  };

  const renderHyrox = () => {
    if (!regsH.length) return <EmptyState text="Cadastre simulados na aba Hyrox para ver os gráficos." />;
    if (modo === "equipe") {
      let linhas = melhorPorAtleta(regsH, valorHyrox, true);
      if (verEquipes) linhas = agruparEquipes(linhas, "media", true);
      const mediasSeg = SEGMENTOS_HYROX.map((_, i) => media(regsH.map((r) => r.dados?.segs?.[i]).filter((v) => typeof v === "number")));
      const maxSeg = Math.max(1, ...mediasSeg.map((v) => v || 0));
      return (
        <>
          <BlocoHy titulo={verEquipes ? "Hyrox por equipe" : "Hyrox da equipe"} icone={<Trophy size={18} color="#E4DE00" />}
            ajuda="Melhor tempo total de cada atleta (só simulados completos).">
            {grafico === "linha"
              ? <LinhasMulti series={montarSeries(regsH.map((r) => ({ atleta: r.atleta, equipe: r.equipe, data: r.data, valor: valorHyrox(r) })).filter((i) => i.valor != null), { porEquipe: verEquipes })} formatar={fmtTempo} menorMelhor destaque={verEquipes ? "" : sessao.atleta} />
              : <RankingBarras linhas={linhas} formatar={fmtTempo} menorMelhor destaque={sessao.atleta} vazio="Nenhum simulado completo ainda." />}
          </BlocoHy>
          <BlocoHy titulo="Média da equipe por estação" icone={<Timer size={18} color="#E4DE00" />} ajuda="Onde a equipe gasta mais tempo.">
            {SEGMENTOS_HYROX.map((nome, i) => mediasSeg[i] == null ? null : (
              <div key={nome} style={{ marginTop: i ? 8 : 0 }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12 }}>
                  <span style={{ color: ehCorridaHyrox(i) ? "#9A9A94" : "#F1EFE9", fontWeight: ehCorridaHyrox(i) ? 500 : 700 }}>{nome}</span>
                  <span style={{ color: "#E4DE00", fontWeight: 800, fontFamily: "'JetBrains Mono', monospace" }}>{fmtTempo(mediasSeg[i])}</span>
                </div>
                <div style={{ height: 5, background: "#26272B", borderRadius: 3, marginTop: 3, overflow: "hidden" }}>
                  <div style={{ width: `${(mediasSeg[i] / maxSeg) * 100}%`, height: "100%", background: ehCorridaHyrox(i) ? "#4B9EEA" : "#E4DE00" }} />
                </div>
              </div>
            ))}
          </BlocoHy>
        </>
      );
    }
    const meus = regsH.filter(ehAtleta);
    const pontos = meus.map((r) => ({ data: r.data, valor: valorHyrox(r) })).filter((p) => p.valor != null);
    const ultimo = [...meus].sort((a, b) => b.data.localeCompare(a.data)).find((r) => r.dados?.segs);
    const melhorV = pontos.length ? Math.min(...pontos.map((p) => p.valor)) : null;
    return (
      <>
        <BlocoHy titulo="Evolução nos simulados" icone={<Trophy size={18} color="#E4DE00" />} ajuda="Tempo total de cada simulado completo.">
          <GraficoEvolucao tipo={grafico} pontos={pontos} formatar={fmtTempo} menorMelhor />
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <MiniStat rotulo="Simulados" valor={meus.length} />
            <MiniStat rotulo="Melhor total" valor={melhorV != null ? fmtTempo(melhorV) : "—"} />
          </div>
        </BlocoHy>
        {ultimo && (
          <BlocoHy titulo="Último simulado x equipe" icone={<Target size={18} color="#E4DE00" />} ajuda={`${ultimo.nome} · ${dataCurtaHy(ultimo.data)} (amarelo = você, cinza = média da equipe)`}>
            {SEGMENTOS_HYROX.map((nome, i) => {
              const v = ultimo.dados.segs[i];
              if (typeof v !== "number") return null;
              const m = media(regsH.map((r) => r.dados?.segs?.[i]).filter((x) => typeof x === "number"));
              const mx = Math.max(v, m || 0, 1);
              return (
                <div key={nome} style={{ marginTop: i ? 9 : 0 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12 }}>
                    <span style={{ color: "#F1EFE9", fontWeight: 600 }}>{nome}</span>
                    <span style={{ fontFamily: "'JetBrains Mono', monospace", color: "#E4DE00", fontWeight: 800 }}>{fmtTempo(v)} <span style={{ color: "#8E8F96", fontWeight: 500 }}>/ {fmtTempo(m)}</span></span>
                  </div>
                  <div style={{ height: 5, background: "#26272B", borderRadius: 3, marginTop: 3, overflow: "hidden" }}><div style={{ width: `${(v / mx) * 100}%`, height: "100%", background: "#E4DE00" }} /></div>
                  <div style={{ height: 3, background: "#26272B", borderRadius: 3, marginTop: 2, overflow: "hidden" }}><div style={{ width: `${((m || 0) / mx) * 100}%`, height: "100%", background: "#8E8F96" }} /></div>
                </div>
              );
            })}
          </BlocoHy>
        )}
      </>
    );
  };

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        {resumo.map((s) => <MiniStat key={s.rotulo} rotulo={s.rotulo} valor={s.valor} />)}
      </div>

      {segmentoToggle(modo, (v) => { setModo(v); setGrafico(v === "equipe" ? "barras" : "linha"); }, [["equipe", "Equipe"], ["individual", "Individual"]])}
      {segmentoToggle(tema, setTema, [["workouts", "Workouts"], ["corrida", "Corrida"], ["hyrox", "Hyrox"]])}

      {modo === "individual" && atletas.length > 0 && (
        <Field label="Atleta">
          <Select value={atletaAtivo} onChange={(e) => setAtletaSel(e.target.value)}>
            {atletas.map((a) => <option key={a} value={a}>{a}</option>)}
          </Select>
        </Field>
      )}
      {modo === "equipe" && temEquipes && segmentoToggle(agrupar, setAgrupar, [["atletas", "Por atleta"], ["equipes", "Por equipe"]])}

      {blocoPeriodo}
      {segmentoToggle(grafico, setGrafico, [["barras", "Gráfico de barras"], ["linha", "Gráfico em linha"]])}

      {tema === "workouts" && renderWorkouts()}
      {tema === "corrida" && renderCorrida()}
      {tema === "hyrox" && renderHyrox()}
    </div>
  );
}

/* ---------------------------- formulário de registro ---------------------------- */
function RegistroHybridForm({ tipo, sessao, nomesSugeridos, salvando, onSalvar, onCancelar }) {
  const [f, setF] = useState({
    data: dataISOLocal(new Date()), nome: "", evento: "", formato: "FOR TIME", tempo: "", reps: "", rx: "RX",
    descricao: "", carga: "", obs: "", tipoCorrida: TIPOS_CORRIDA[0], km: "", fc: "", categoria: CATEGORIAS_HYROX[0],
    segs: SEGMENTOS_HYROX.map(() => ""),
  });
  const [erro, setErro] = useState("");
  const set = (k, v) => setF((p) => ({ ...p, [k]: v }));

  const totalHyrox = f.segs.map(parseTempo).reduce((s, v) => s + (v || 0), 0);
  const preenchidos = f.segs.filter((s) => parseTempo(s) != null).length;

  const confirmar = () => {
    const base = { tipo, atleta: sessao.atleta, equipe: sessao.equipe, data: f.data };
    if (!f.data) return setErro("Informe a data.");
    if (tipo === "prova" || tipo === "treino") {
      if (!f.nome.trim()) return setErro("Informe o nome do workout.");
      const amrap = f.formato === "AMRAP";
      const tempoSeg = parseTempo(f.tempo);
      const reps = Number(String(f.reps).replace(",", "."));
      if (amrap && (!f.reps.trim() || isNaN(reps))) return setErro("Informe as repetições (ex: 142).");
      if (!amrap && tempoSeg == null) return setErro("Informe o tempo no formato mm:ss (ex: 12:45).");
      return onSalvar({ ...base, nome: f.nome.trim(), dados: {
        formato: f.formato, rx: f.rx, evento: f.evento.trim(), descricao: f.descricao.trim(), carga: f.carga.trim(), obs: f.obs.trim(),
        ...(amrap ? { reps } : { tempoSeg }),
      } });
    }
    if (tipo === "corrida") {
      const km = Number(String(f.km).replace(",", "."));
      const tempoSeg = parseTempo(f.tempo);
      if (!km || km <= 0) return setErro("Informe a distância em km.");
      if (tempoSeg == null || tempoSeg <= 0) return setErro("Informe o tempo no formato mm:ss ou h:mm:ss.");
      const fc = f.fc.trim() ? Number(f.fc) : null;
      return onSalvar({ ...base, nome: `${f.tipoCorrida} · ${fmtKm(km)}`, dados: {
        tipoCorrida: f.tipoCorrida, km, tempoSeg, paceSeg: tempoSeg / km, fc: fc && !isNaN(fc) ? fc : null, obs: f.obs.trim(),
      } });
    }
    // hyrox
    if (preenchidos === 0) return setErro("Preencha pelo menos um tempo (mm:ss).");
    if (f.segs.some((s) => s.trim() && parseTempo(s) == null)) return setErro("Há tempo inválido. Use mm:ss (ex: 4:35).");
    return onSalvar({ ...base, nome: f.nome.trim() || `Simulado HYROX ${f.categoria}`, dados: {
      categoria: f.categoria, obs: f.obs.trim(), segs: f.segs.map(parseTempo), totalSeg: totalHyrox, completo: preenchidos === SEGMENTOS_HYROX.length,
    } });
  };

  const amrap = f.formato === "AMRAP";
  return (
    <div>
      <div style={{ fontSize: 12.5, color: "#9A9A94", marginBottom: 12 }}>Atleta: <b style={{ color: "#E4DE00" }}>{sessao.atleta}</b> · {sessao.equipe}</div>
      <Field label="Data"><TextInput type="date" value={f.data} onChange={(e) => set("data", e.target.value)} /></Field>

      {(tipo === "prova" || tipo === "treino") && (
        <>
          <Field label={tipo === "prova" ? "Workout / prova" : "Workout fechado"}>
            <TextInput list="hy-nomes" value={f.nome} onChange={(e) => set("nome", e.target.value)} placeholder={tipo === "prova" ? "Ex: Workout 1 – Fran" : "Ex: Murph, Cindy, 5 rounds..."} />
            <datalist id="hy-nomes">{nomesSugeridos.map((n) => <option key={n} value={n} />)}</datalist>
          </Field>
          {tipo === "prova" && <Field label="Evento (opcional)"><TextInput value={f.evento} onChange={(e) => set("evento", e.target.value)} placeholder="Ex: Campeonato Interno, Open" /></Field>}
          {tipo === "treino" && <Field label="Descrição do treino (opcional)"><TextArea value={f.descricao} onChange={(e) => set("descricao", e.target.value)} placeholder="Exercícios, reps, cargas..." /></Field>}
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Formato"><Select value={f.formato} onChange={(e) => set("formato", e.target.value)}>{FORMATOS.map((o) => <option key={o}>{o}</option>)}</Select></Field></div>
            <div style={{ flex: 1 }}><Field label="RX / Scaled"><Select value={f.rx} onChange={(e) => set("rx", e.target.value)}><option>RX</option><option>Scaled</option></Select></Field></div>
          </div>
          {amrap
            ? <Field label="Repetições totais"><TextInput inputMode="decimal" value={f.reps} onChange={(e) => set("reps", e.target.value)} placeholder="Ex: 142" /></Field>
            : <><Field label="Tempo (mm:ss)"><TempoInput value={f.tempo} onChange={(v) => set("tempo", v)} placeholder="Ex: 12:45" /></Field><DicaTempo /></>}
          <Field label="Carga (opcional)"><TextInput value={f.carga} onChange={(e) => set("carga", e.target.value)} placeholder="Ex: 43 kg / 30 lb" /></Field>
        </>
      )}

      {tipo === "corrida" && (
        <>
          <Field label="Tipo"><Select value={f.tipoCorrida} onChange={(e) => set("tipoCorrida", e.target.value)}>{TIPOS_CORRIDA.map((o) => <option key={o}>{o}</option>)}</Select></Field>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Distância (km)"><TextInput inputMode="decimal" value={f.km} onChange={(e) => set("km", e.target.value)} placeholder="Ex: 5" /></Field></div>
            <div style={{ flex: 1 }}><Field label="Tempo total"><TempoInput value={f.tempo} onChange={(v) => set("tempo", v)} placeholder="Ex: 24:30" /></Field></div>
          </div>
          <DicaTempo />
          {parseTempo(f.tempo) && Number(String(f.km).replace(",", ".")) > 0 && (
            <div style={{ fontSize: 13, color: "#E4DE00", fontWeight: 700, marginBottom: 12 }}>Pace: {fmtPace(parseTempo(f.tempo) / Number(String(f.km).replace(",", ".")))}</div>
          )}
          <Field label="FC média (opcional)"><TextInput inputMode="numeric" value={f.fc} onChange={(e) => set("fc", e.target.value)} placeholder="Ex: 165" /></Field>
        </>
      )}

      {tipo === "hyrox" && (
        <>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Categoria"><Select value={f.categoria} onChange={(e) => set("categoria", e.target.value)}>{CATEGORIAS_HYROX.map((o) => <option key={o}>{o}</option>)}</Select></Field></div>
            <div style={{ flex: 2 }}><Field label="Nome (opcional)"><TextInput value={f.nome} onChange={(e) => set("nome", e.target.value)} placeholder="Ex: Simulado 3" /></Field></div>
          </div>
          <div style={{ fontSize: 12, color: "#8E8F96", marginBottom: 8 }}>Tempo de cada parcial: digite só números (435 vira 4:35). Pode deixar em branco o que não fez.</div>
          {SEGMENTOS_HYROX.map((nome, i) => (
            <div key={nome} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
              <span style={{ flex: 1, fontSize: 12.5, color: ehCorridaHyrox(i) ? "#4B9EEA" : "#F1EFE9", fontWeight: ehCorridaHyrox(i) ? 500 : 700 }}>{nome}</span>
              <TempoInput value={f.segs[i]} placeholder="mm:ss" style={{ width: 96, padding: "7px 10px" }}
                onChange={(v) => setF((p) => ({ ...p, segs: p.segs.map((s, j) => (j === i ? v : s)) }))} />
            </div>
          ))}
          <div style={{ fontSize: 14, color: "#E4DE00", fontWeight: 800, margin: "10px 0 14px" }}>
            Total: {fmtTempo(totalHyrox)} <span style={{ color: "#8E8F96", fontWeight: 500, fontSize: 12 }}>({preenchidos}/{SEGMENTOS_HYROX.length} parciais)</span>
          </div>
        </>
      )}

      <Field label="Observações (opcional)"><TextInput value={f.obs} onChange={(e) => set("obs", e.target.value)} placeholder="Como foi, sensação, ajustes..." /></Field>
      {erro && <div style={{ color: "#E6483F", fontSize: 12.5, marginBottom: 10 }}>{erro}</div>}
      <div style={{ display: "flex", gap: 10 }}>
        <GhostButton onClick={onCancelar} style={{ flex: 1 }}>Cancelar</GhostButton>
        <PrimaryButton onClick={confirmar} disabled={salvando} style={{ flex: 2 }}><Save size={16} /> {salvando ? "Salvando..." : "Salvar"}</PrimaryButton>
      </div>
    </div>
  );
}

/* ---------------------------- listas por tipo ---------------------------- */
function RegistroHybridCard({ r, minha, onExcluir }) {
  const d = r.dados || {};
  let destaque = "";
  let linhas = [];
  let badges = [];
  if (r.tipo === "prova" || r.tipo === "treino") {
    const v = valorWorkout(r);
    destaque = v == null ? "—" : fmtWorkout(v, d.formato);
    badges = [d.formato, d.rx].filter(Boolean);
    if (d.evento) linhas.push(`Evento: ${d.evento}`);
    if (d.carga) linhas.push(`Carga: ${d.carga}`);
    if (d.descricao) linhas.push(d.descricao);
  } else if (r.tipo === "corrida") {
    destaque = fmtTempo(d.tempoSeg);
    badges = [d.tipoCorrida, fmtKm(d.km || 0), fmtPace(d.paceSeg)].filter(Boolean);
    if (d.fc) linhas.push(`FC média: ${d.fc} bpm`);
  } else {
    destaque = fmtTempo(d.totalSeg);
    badges = [d.categoria, d.completo ? "Completo" : "Parcial"].filter(Boolean);
    const segs = d.segs || [];
    const run = segs.filter((_, i) => ehCorridaHyrox(i)).reduce((s, v) => s + (v || 0), 0);
    const est = segs.filter((_, i) => !ehCorridaHyrox(i)).reduce((s, v) => s + (v || 0), 0);
    linhas.push(`Corridas: ${fmtTempo(run)} · Estações: ${fmtTempo(est)}`);
  }
  if (d.obs) linhas.push(d.obs);
  return (
    <div style={{ ...cardHy, borderLeft: `3px solid ${minha ? "#E4DE00" : "#3A3B40"}` }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14.5, color: "#FFFFFF", fontWeight: 800 }}>{r.nome}</div>
          <div style={{ fontSize: 11.5, color: "#8E8F96", marginTop: 3 }}>{r.atleta} · {r.equipe} · {dataCurtaHy(r.data)}</div>
        </div>
        <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 22, color: "#E4DE00", letterSpacing: "0.03em", lineHeight: 1 }}>{destaque}</div>
        <button onClick={() => onExcluir(r)} title="Excluir" style={{ background: "none", border: "none", color: "#8E8F96", cursor: "pointer", padding: 2 }}><Trash2 size={15} /></button>
      </div>
      {badges.length > 0 && <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>{badges.map((b) => <Badge key={b}>{b}</Badge>)}</div>}
      {linhas.map((l, i) => <div key={i} style={{ fontSize: 12, color: "#9A9A94", marginTop: 6, lineHeight: 1.4, whiteSpace: "pre-wrap" }}>{l}</div>)}
    </div>
  );
}

const INFO_ABAS_HYBRID = {
  prova: { titulo: "WORKOUTS · TEMPO DE CADA PROVA", ajuda: "Registre o tempo (ou reps) de cada workout de prova.", vazio: "Nenhum tempo de prova registrado ainda." },
  treino: { titulo: "TREINO ESPECÍFICO", ajuda: "Workouts fechados: use o mesmo nome para comparar a evolução e a equipe.", vazio: "Nenhum treino específico registrado ainda." },
  corrida: { titulo: "MÉTRICAS DE CORRIDA", ajuda: "Distância, tempo e pace de cada corrida.", vazio: "Nenhuma corrida registrada ainda." },
  hyrox: { titulo: "SIMULADOS DE HYROX", ajuda: "8 corridas de 1 km + 8 estações, com o tempo de cada parcial.", vazio: "Nenhum simulado registrado ainda." },
};

function ListaHybrid({ tipo, registros, sessao, onNovo, onExcluir }) {
  const [soMeus, setSoMeus] = useState(false);
  const info = INFO_ABAS_HYBRID[tipo];
  const meu = (r) => normalizarTexto(r.atleta) === normalizarTexto(sessao.atleta);
  const lista = registros
    .filter((r) => r.tipo === tipo && (!soMeus || meu(r)))
    .sort((a, b) => b.data.localeCompare(a.data) || String(b.criadoEm).localeCompare(String(a.criadoEm)));
  return (
    <div>
      <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 20, color: "#E4DE00", letterSpacing: "0.04em" }}>{info.titulo}</div>
      <div style={{ fontSize: 12, color: "#8E8F96", margin: "4px 0 12px", lineHeight: 1.4 }}>{info.ajuda}</div>
      <PrimaryButton onClick={onNovo} style={{ width: "100%", marginBottom: 12 }}><Plus size={16} /> Novo registro</PrimaryButton>
      <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
        <button onClick={() => setSoMeus(false)} style={chipHy(!soMeus)}>Todos</button>
        <button onClick={() => setSoMeus(true)} style={chipHy(soMeus)}>Meus</button>
      </div>
      {lista.length === 0 ? <EmptyState text={info.vazio} /> : lista.map((r) => <RegistroHybridCard key={r.id} r={r} minha={meu(r)} onExcluir={onExcluir} />)}
    </div>
  );
}

/* ---------------------------- acesso (código único) ---------------------------- */
function AcessoHybrid({ onEntrar, erro, entrando, inicial }) {
  const [codigo, setCodigo] = useState("");
  const [atleta, setAtleta] = useState(inicial?.atleta || "");
  const [equipe, setEquipe] = useState(inicial?.equipe || EQUIPE_PADRAO_HYBRID);
  const enviar = () => { if (codigo.trim() && atleta.trim()) onEntrar({ codigo: codigo.trim(), atleta: atleta.trim(), equipe: equipe.trim() || EQUIPE_PADRAO_HYBRID }); };
  return (
    <div style={{ maxWidth: 420, margin: "0 auto", padding: "56px 20px" }}>
      <div style={{ textAlign: "center", marginBottom: 26 }}>
        <div style={{ width: 54, height: 54, borderRadius: 12, background: "#E4DE00", display: "inline-flex", alignItems: "center", justifyContent: "center" }}><Trophy size={28} color="#0A0A0A" /></div>
        <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 30, color: "#FFFFFF", letterSpacing: "0.04em", marginTop: 12, lineHeight: 1 }}>{NOME_PASTA_HYBRID}</div>
        <div style={{ fontSize: 12, color: "#9A9A94", marginTop: 8, lineHeight: 1.5 }}>Resultados, provas, treinos específicos, corrida e simulados de HYROX da equipe.</div>
      </div>
      <Field label="Código de acesso"><TextInput type="password" value={codigo} onChange={(e) => setCodigo(e.target.value)} placeholder="Código da equipe" onKeyDown={(e) => e.key === "Enter" && enviar()} /></Field>
      <Field label="Seu nome"><TextInput value={atleta} onChange={(e) => setAtleta(e.target.value)} placeholder="Nome e sobrenome" /></Field>
      <Field label="Equipe"><TextInput value={equipe} onChange={(e) => setEquipe(e.target.value)} placeholder={EQUIPE_PADRAO_HYBRID} /></Field>
      {erro && <div style={{ color: "#E6483F", fontSize: 12.5, marginBottom: 12 }}>{erro}</div>}
      <PrimaryButton onClick={enviar} disabled={entrando} style={{ width: "100%" }}><Lock size={15} /> {entrando ? "Entrando..." : "Entrar"}</PrimaryButton>
    </div>
  );
}

/* ---------------------------- tela principal da pasta ---------------------------- */
const ABAS_HYBRID = [
  { id: "resultados", label: "Resultados", icon: BarChart3 },
  { id: "prova", label: "Provas", icon: Timer },
  { id: "treino", label: "Específico", icon: Target },
  { id: "corrida", label: "Corrida", icon: Activity },
  { id: "hyrox", label: "Hyrox", icon: Trophy },
];

function HybridCantil() {
  const [sessao, setSessao] = useState(() => lerSessaoHybrid());
  const [registros, setRegistros] = useState([]);
  const [carregando, setCarregando] = useState(!!lerSessaoHybrid());
  const [entrando, setEntrando] = useState(false);
  const [erroAcesso, setErroAcesso] = useState("");
  const [aba, setAba] = useState("resultados");
  const [novoTipo, setNovoTipo] = useState(null);
  const [salvando, setSalvando] = useState(false);
  const [toast, setToast] = useState("");
  const mostrarToast = (m) => { setToast(m); setTimeout(() => setToast(""), 2200); };

  const carregar = useCallback(async (s) => {
    const r = await hybridListarDb(s.codigo);
    if (r.erro === "codigo") { salvarSessaoHybrid(null); setSessao(null); setErroAcesso("O código mudou. Digite o novo código."); return false; }
    if (r.erro) { setErroAcesso("Sem conexão com o banco. Tente de novo."); return false; }
    setRegistros(r.dados);
    return true;
  }, []);

  useEffect(() => {
    if (!sessao) { setCarregando(false); return; }
    (async () => { await carregar(sessao); setCarregando(false); })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aba]);

  const entrar = async (s) => {
    setEntrando(true);
    setErroAcesso("");
    const r = await hybridListarDb(s.codigo);
    setEntrando(false);
    if (r.erro === "codigo") return setErroAcesso("Código incorreto.");
    if (r.erro) return setErroAcesso("Não consegui conectar. Confirme se rodou o hybrid_cantil.sql no Supabase.");
    salvarSessaoHybrid(s);
    setRegistros(r.dados);
    setSessao(s);
  };
  const sair = () => { salvarSessaoHybrid(null); setSessao(null); setRegistros([]); };

  const salvar = async (reg) => {
    if (salvando) return;
    setSalvando(true);
    const novo = await hybridSalvarDb(sessao.codigo, reg);
    setSalvando(false);
    if (!novo) { mostrarToast("Não consegui salvar. Tente de novo."); return; }
    setRegistros((prev) => [novo, ...prev]);
    setNovoTipo(null);
    mostrarToast("Registro salvo!");
  };
  const excluir = async (r) => {
    const minha = normalizarTexto(r.atleta) === normalizarTexto(sessao.atleta);
    let senha = "";
    if (minha) { if (!window.confirm("Excluir este registro?")) return; }
    else {
      senha = window.prompt("Só o treinador apaga registro de outro atleta. Senha do treinador:") || "";
      if (!senha) return;
    }
    const ok = await hybridExcluirDb(sessao.codigo, r.id, sessao.atleta, senha);
    if (ok) { setRegistros((prev) => prev.filter((x) => x.id !== r.id)); mostrarToast("Registro excluído"); }
    else mostrarToast("Não consegui excluir (senha incorreta?)");
  };

  const fundo = { background: "#0A0A0A", minHeight: "100vh", fontFamily: "'Inter', sans-serif" };
  if (!sessao) {
    return <div style={fundo}><style>{FONT_IMPORT}</style><AcessoHybrid onEntrar={entrar} erro={erroAcesso} entrando={entrando} inicial={lerSessaoHybrid()} /></div>;
  }
  const nomesSugeridos = [...new Set(registros.filter((r) => r.tipo === "prova" || r.tipo === "treino").map((r) => r.nome))];
  return (
    <div onFocus={rolarCampoParaVisivel} style={fundo}>
      <style>{FONT_IMPORT}</style>
      <div style={{ padding: "20px 16px 10px", borderBottom: "1px solid #222" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", maxWidth: 640, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ width: 38, height: 38, borderRadius: 8, background: "#E4DE00", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Trophy size={20} color="#0A0A0A" /></div>
            <div>
              <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 22, color: "#FFFFFF", letterSpacing: "0.03em", lineHeight: 1 }}>HYBRID</div>
              <div style={{ fontSize: 10, color: "#E4DE00", letterSpacing: "0.4em", marginTop: 3 }}>CANTIL</div>
            </div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 12, color: "#F1EFE9", fontWeight: 700 }}>{sessao.atleta}</div>
            <button onClick={sair} style={{ background: "none", border: "none", color: "#8E8F96", fontSize: 11, cursor: "pointer", padding: 0 }}>Sair</button>
          </div>
        </div>
      </div>

      <div style={{ padding: "16px 16px 100px", maxWidth: 640, margin: "0 auto" }}>
        {carregando ? <Spinner /> : (
          <>
            {erroAcesso && <div style={{ color: "#FF8A3D", fontSize: 12.5, marginBottom: 10 }}>{erroAcesso}</div>}
            {aba === "resultados"
              ? <ResultadosHybrid registros={registros} sessao={sessao} />
              : <ListaHybrid tipo={aba} registros={registros} sessao={sessao} onNovo={() => setNovoTipo(aba)} onExcluir={excluir} />}
          </>
        )}
      </div>

      {novoTipo && (
        <Sheet title={INFO_ABAS_HYBRID[novoTipo].titulo} onClose={() => setNovoTipo(null)}>
          <RegistroHybridForm tipo={novoTipo} sessao={sessao} nomesSugeridos={nomesSugeridos} salvando={salvando} onSalvar={salvar} onCancelar={() => setNovoTipo(null)} />
        </Sheet>
      )}
      <Toast text={toast} />

      <div style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: "#1C1D20", borderTop: "1px solid #2E2F34", display: "flex", padding: "8px 6px 14px" }}>
        <div style={{ display: "flex", maxWidth: 640, margin: "0 auto", width: "100%" }}>
          {ABAS_HYBRID.map((a) => {
            const Icon = a.icon;
            const ativo = aba === a.id;
            return (
              <button key={a.id} onClick={() => setAba(a.id)} style={{ flex: 1, background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 3, color: ativo ? "#E4DE00" : "#8E8F96", padding: "6px 0" }}>
                <Icon size={20} />
                <span style={{ fontSize: 10.5, fontWeight: 600 }}>{a.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// Cartão da pasta dentro de PROGRAMAÇÕES (visão do treinador): abrir, copiar link e trocar o código
function PastaHybridCard({ senha, pedir, onToast }) {
  const abrir = () => { window.location.hash = "#/hybrid"; };
  const copiar = async (e) => {
    e.stopPropagation();
    const ok = await copyToClipboard(buildShareUrlHybrid());
    if (onToast) onToast(ok ? "Link da pasta copiado!" : "Não consegui copiar o link");
  };
  const trocarCodigo = (e) => {
    e.stopPropagation();
    pedir(async () => {
      const novo = (window.prompt("Novo código de acesso da pasta HYBRID CANTIL (vale para todos):") || "").trim();
      if (!novo) return;
      const ok = await hybridDefinirCodigoDb(senha, novo);
      if (onToast) onToast(ok ? "Código alterado!" : "Não consegui alterar (rode o hybrid_cantil.sql)");
    });
  };
  return (
    <div
      onClick={abrir}
      style={{ width: "100%", boxSizing: "border-box", cursor: "pointer", background: "#1A1B1E", border: "1px solid #26272B", borderLeft: "3px solid #E4DE00", borderRadius: 12, padding: "14px 14px", marginBottom: 10 }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 42, height: 42, borderRadius: 10, background: "rgba(228,222,0,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Trophy size={22} color="#E4DE00" />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 16, color: "#FFFFFF", letterSpacing: "0.03em" }}>{NOME_PASTA_HYBRID}</div>
          <div style={{ fontSize: 11.5, color: "#8E8F96", marginTop: 5, lineHeight: 1.4 }}>{DESCRICAO_PASTA_HYBRID}</div>
        </div>
        <ChevronRight size={18} color="#8E8F96" />
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <button onClick={copiar} style={{ ...chipHy(false), display: "flex", alignItems: "center", gap: 6 }}><Copy size={13} /> Copiar link</button>
        <button onClick={trocarCodigo} style={{ ...chipHy(false), display: "flex", alignItems: "center", gap: 6 }}><KeyRound size={13} /> Alterar código</button>
      </div>
    </div>
  );
}


/* =================================================================
   CT CANTIL · página de apresentação (planos, horários, WhatsApp) + QR Code
   Link público: #/ct  ·  Conteúdo editável pelo treinador (tabela ct_info)
================================================================= */

const CT_INFO_PADRAO = {
  titulo: "CT CANTIL",
  chamada: "Treino funcional e híbrido para todos os níveis.",
  sobre: "Aulas em grupo, acompanhamento de perto e uma comunidade que treina junto. Veja os planos e horários abaixo e fale com a gente pelo WhatsApp.",
  planos: [
    { id: "p1", nome: "Aula experimental", preco: "Fale com a gente", descricao: "Venha conhecer o CT e fazer um treino com a turma.", destaque: false },
    { id: "p2", nome: "Plano mensal", preco: "Consulte os valores", descricao: "Acesso às aulas do CT durante o mês.", destaque: true },
  ],
  horarios: [{ id: "h1", dia: "Consulte", horas: "Horários de atendimento em breve" }],
  endereco: "",
  mapaUrl: "",
  whatsapp: "",
  mensagem: "Olá! Vi o QR Code do CT Cantil e gostaria de saber mais sobre os planos.",
  instagram: "",
  qrLink: "",
};

function buildShareUrlCT() {
  const { origin, pathname } = window.location;
  return `${origin}${pathname}#/ct`;
}
function parseHashCT() {
  return /^#\/ct\/?$/.test(window.location.hash);
}
function urlWhatsapp(info) {
  let n = String(info.whatsapp || "").replace(/\D/g, "");
  if (!n) return "";
  if (n.length <= 11) n = "55" + n; // DDD + número => acrescenta o Brasil
  return `https://wa.me/${n}?text=${encodeURIComponent(info.mensagem || "")}`;
}
function urlMapa(info) {
  if (info.mapaUrl && info.mapaUrl.trim()) return info.mapaUrl.trim();
  if (info.endereco && info.endereco.trim()) return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(info.endereco.trim())}`;
  return "";
}
async function fetchCtInfo() {
  const { data, error } = await supabase.from("ct_info").select("dados").eq("id", 1).maybeSingle();
  if (error) { console.error(error); return { info: CT_INFO_PADRAO, ok: false }; }
  return { info: { ...CT_INFO_PADRAO, ...((data && data.dados) || {}) }, ok: true };
}
async function salvarCtInfoDb(info) {
  const { error } = await supabase.from("ct_info").upsert({ id: 1, dados: info, atualizado_em: new Date().toISOString() });
  if (error) { console.error(error); return false; }
  return true;
}

/* ---------------------------- QR Code (gerador próprio, sem biblioteca) ---------------------------- */
// ---- Gerador de QR Code (nível de correção M, versões 1 a 10, modo bytes/UTF-8) ----
function qrMatriz(texto, forca) {
  const bytes = Array.from(new TextEncoder().encode(String(texto)));
  const ECC = [10, 16, 26, 18, 24, 16, 18, 22, 22, 26]; // códigos de correção por bloco (versão 1..10)
  const BLK = [1, 1, 1, 2, 2, 4, 4, 4, 5, 5]; // blocos (versão 1..10)
  const bruto = (v) => {
    let r = (16 * v + 128) * v + 64;
    if (v >= 2) { const n = Math.floor(v / 7) + 2; r -= (25 * n - 10) * n - 55; if (v >= 7) r -= 36; }
    return r;
  };
  const dadosCap = (v) => Math.floor(bruto(v) / 8) - ECC[v - 1] * BLK[v - 1];
  let ver = 0;
  for (let v = 1; v <= 10; v++) {
    if (4 + (v < 10 ? 8 : 16) + 8 * bytes.length <= dadosCap(v) * 8) { ver = v; break; }
  }
  if (!ver) throw new Error("Link longo demais para o QR Code");
  // bits de dados
  const bits = [];
  const poe = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >>> i) & 1); };
  poe(4, 4); poe(bytes.length, ver < 10 ? 8 : 16);
  bytes.forEach((b) => poe(b, 8));
  const capBits = dadosCap(ver) * 8;
  poe(0, Math.min(4, capBits - bits.length));
  while (bits.length % 8) bits.push(0);
  for (let pad = 0xec; bits.length < capBits; pad ^= 0xec ^ 0x11) poe(pad, 8);
  const dados = [];
  for (let i = 0; i < bits.length; i += 8) dados.push(parseInt(bits.slice(i, i + 8).join(""), 2));
  // Reed-Solomon
  const mul = (x, y) => { let z = 0; for (let i = 7; i >= 0; i--) { z = (z << 1) ^ ((z >>> 7) * 0x11d); z ^= ((y >>> i) & 1) * x; } return z; };
  const divisor = (grau) => {
    const r = new Array(grau).fill(0); r[grau - 1] = 1; let raiz = 1;
    for (let i = 0; i < grau; i++) {
      for (let j = 0; j < r.length; j++) { r[j] = mul(r[j], raiz); if (j + 1 < r.length) r[j] ^= r[j + 1]; }
      raiz = mul(raiz, 2);
    }
    return r;
  };
  const resto = (dat, div) => {
    const r = new Array(div.length).fill(0);
    dat.forEach((b) => { const f = b ^ r.shift(); r.push(0); div.forEach((c, i) => { r[i] ^= mul(c, f); }); });
    return r;
  };
  const nBlocos = BLK[ver - 1], eccLen = ECC[ver - 1];
  const brutoCw = Math.floor(bruto(ver) / 8);
  const nCurtos = nBlocos - (brutoCw % nBlocos), lenCurto = Math.floor(brutoCw / nBlocos);
  const div = divisor(eccLen);
  const blocos = [];
  for (let i = 0, k = 0; i < nBlocos; i++) {
    const n = lenCurto - eccLen + (i < nCurtos ? 0 : 1);
    const dat = dados.slice(k, k + n); k += n;
    const ecc = resto(dat, div);
    if (i < nCurtos) dat.push(0);
    blocos.push(dat.concat(ecc));
  }
  const final = [];
  for (let i = 0; i < blocos[0].length; i++) {
    blocos.forEach((b, j) => { if (i !== lenCurto - eccLen || j >= nCurtos) final.push(b[i]); });
  }
  // matriz
  const size = ver * 4 + 17;
  const mod = Array.from({ length: size }, () => new Array(size).fill(false));
  const fn = Array.from({ length: size }, () => new Array(size).fill(false));
  const set = (x, y, v) => { mod[y][x] = v; fn[y][x] = true; };
  for (let i = 0; i < size; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }
  const finder = (x, y) => {
    for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) {
      const d = Math.max(Math.abs(dx), Math.abs(dy)), xx = x + dx, yy = y + dy;
      if (xx >= 0 && xx < size && yy >= 0 && yy < size) set(xx, yy, d !== 2 && d !== 4);
    }
  };
  finder(3, 3); finder(size - 4, 3); finder(3, size - 4);
  const nAl = ver === 1 ? 0 : Math.floor(ver / 7) + 2;
  const pos = [];
  if (nAl) {
    const passo = ver === 32 ? 26 : Math.ceil((ver * 4 + 4) / (nAl * 2 - 2)) * 2;
    pos.push(6);
    for (let p = size - 7, c = 1; c < nAl; p -= passo, c++) pos.splice(1, 0, p);
  }
  pos.forEach((px, i) => pos.forEach((py, j) => {
    if ((i === 0 && j === 0) || (i === 0 && j === nAl - 1) || (i === nAl - 1 && j === 0)) return;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) set(px + dx, py + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
  }));
  const formato = (mask) => {
    const d = (0 << 3) | mask; // nível M = 0
    let r = d; for (let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
    const b = ((d << 10) | r) ^ 0x5412;
    const bit = (i) => ((b >>> i) & 1) !== 0;
    for (let i = 0; i <= 5; i++) set(8, i, bit(i));
    set(8, 7, bit(6)); set(8, 8, bit(7)); set(7, 8, bit(8));
    for (let i = 9; i < 15; i++) set(14 - i, 8, bit(i));
    for (let i = 0; i < 8; i++) set(size - 1 - i, 8, bit(i));
    for (let i = 8; i < 15; i++) set(8, size - 15 + i, bit(i));
    set(8, size - 8, true);
  };
  formato(0);
  if (ver >= 7) {
    let r = ver; for (let i = 0; i < 12; i++) r = (r << 1) ^ ((r >>> 11) * 0x1f25);
    const b = (ver << 12) | r;
    for (let i = 0; i < 18; i++) { const c = ((b >>> i) & 1) !== 0, a = size - 11 + (i % 3), q = Math.floor(i / 3); set(a, q, c); set(q, a, c); }
  }
  // dados em zigue-zague
  let k = 0;
  for (let dir = size - 1; dir >= 1; dir -= 2) {
    if (dir === 6) dir = 5;
    for (let v = 0; v < size; v++) for (let j = 0; j < 2; j++) {
      const x = dir - j, y = ((dir + 1) & 2) === 0 ? size - 1 - v : v;
      if (!fn[y][x] && k < final.length * 8) { mod[y][x] = ((final[k >>> 3] >>> (7 - (k & 7))) & 1) !== 0; k++; }
    }
  }
  // máscara: escolhe a de menor penalidade
  const inverte = [
    (x, y) => (x + y) % 2 === 0, (x, y) => y % 2 === 0, (x, y) => x % 3 === 0, (x, y) => (x + y) % 3 === 0,
    (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0, (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
    (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0, (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
  ];
  const aplica = (m) => { for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) if (!fn[y][x] && inverte[m](x, y)) mod[y][x] = !mod[y][x]; };
  const penal = () => {
    let p = 0;
    const linhas = [mod, Array.from({ length: size }, (_, x) => mod.map((r) => r[x]))];
    linhas.forEach((grade) => grade.forEach((r) => {
      let run = 1;
      for (let i = 1; i <= size; i++) {
        if (i < size && r[i] === r[i - 1]) run++; else { if (run >= 5) p += 3 + (run - 5); run = 1; }
      }
      const s = r.map((c) => (c ? "1" : "0")).join("");
      for (let i = 0; i + 11 <= size; i++) { const t = s.slice(i, i + 11); if (t === "10111010000" || t === "00001011101") p += 40; }
    }));
    for (let y = 0; y < size - 1; y++) for (let x = 0; x < size - 1; x++) if (mod[y][x] === mod[y][x + 1] && mod[y][x] === mod[y + 1][x] && mod[y][x] === mod[y + 1][x + 1]) p += 3;
    const escuros = mod.reduce((s, r) => s + r.filter(Boolean).length, 0);
    p += (Math.ceil(Math.abs(escuros * 20 - size * size * 10) / (size * size)) - 1) * 10;
    return p;
  };
  let melhor = 0, melhorP = Infinity;
  for (let m = 0; m < 8; m++) { aplica(m); formato(m); const p = penal(); if (p < melhorP) { melhor = m; melhorP = p; } aplica(m); }
  const esc = forca == null ? melhor : forca; aplica(esc); formato(esc);
  return mod;
}

// Gera o PNG do QR Code (com margem branca) e devolve como data URL
function qrParaPng(texto, escala = 12) {
  const m = qrMatriz(texto);
  const borda = 4;
  const lado = (m.length + borda * 2) * escala;
  const c = document.createElement("canvas");
  c.width = lado; c.height = lado;
  const ctx = c.getContext("2d");
  ctx.fillStyle = "#FFFFFF";
  ctx.fillRect(0, 0, lado, lado);
  ctx.fillStyle = "#000000";
  m.forEach((linha, y) => linha.forEach((v, x) => { if (v) ctx.fillRect((x + borda) * escala, (y + borda) * escala, escala, escala); }));
  return c.toDataURL("image/png");
}

